    "mail_from": "receipts@example.com",
    "default_zone": "domestic",
    "loyalty_enabled": True,
    "webhooks_enabled": False,
}

_OVERRIDES: dict[str, object] = {}


class FeatureFlag:
    def __init__(self, name: str, enabled: bool = False) -> None:
        self.name = name
        self.enabled = enabled

    def enable(self) -> None:
        self.enabled = True

    def disable(self) -> None:
        self.enabled = False

    def is_on(self) -> bool:
        return bool(self.enabled)


_FLAGS: dict[str, FeatureFlag] = {
    "include_tax_in_reports": FeatureFlag("include_tax_in_reports", False),
    "signed_webhooks": FeatureFlag("signed_webhooks", True),
    "quiet_hours": FeatureFlag("quiet_hours", False),
}


def get_setting(key: str, default: object | None = None) -> object:
    if key in _OVERRIDES:
        return _OVERRIDES[key]
    if key in _DEFAULTS:
        return _DEFAULTS[key]
    return default


def set_setting(key: str, value: object) -> None:
    _OVERRIDES[key] = value


def clear_override(key: str) -> None:
    _OVERRIDES.pop(key, None)


def timezone() -> str:
    return str(get_setting("timezone", "UTC"))


def currency() -> str:
    return str(get_setting("currency", "USD"))


def tax_rate() -> float:
    return float(get_setting("tax_rate", 0.0) or 0.0)


def mail_from() -> str:
    return str(get_setting("mail_from", "receipts@example.com"))


def default_zone() -> str:
    return str(get_setting("default_zone", "domestic"))


def loyalty_enabled() -> bool:
    return bool(get_setting("loyalty_enabled", True))


def webhooks_enabled() -> bool:
    return bool(get_setting("webhooks_enabled", False))


def flag(name: str) -> FeatureFlag:
    if name not in _FLAGS:
        _FLAGS[name] = FeatureFlag(name, False)
    return _FLAGS[name]


def flag_enabled(name: str) -> bool:
    return flag(name).is_on()


def enable_flag(name: str) -> None:
    flag(name).enable()


def disable_flag(name: str) -> None:
    flag(name).disable()


def snapshot() -> dict[str, object]:
    data = dict(_DEFAULTS)
    data.update(_OVERRIDES)
    data["flags"] = {name: item.is_on() for name, item in _FLAGS.items()}
    return data


def reset_store() -> None:
    _OVERRIDES.clear()
    for item in _FLAGS.values():
        item.disable()
    _FLAGS["signed_webhooks"].enable()

"""FastAPI app wiring."""

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel

from app import (
    auth,
    calculator,
    inventory,
    orders,
    reports,
    users,
    validators,
)


app = FastAPI(title="issue-pilot-benchmark")


class LoginBody(BaseModel):
    email: str
    password: str


class OrderItem(BaseModel):
    sku: str = "widget"
    price: float
    qty: int


class CreateOrderBody(BaseModel):
    items: list[OrderItem]
    coupon: str | None = None


class EmailBody(BaseModel):
    email: str


def _bearer(authorization: str) -> str:
    if not authorization or not authorization.lower().startswith("bearer "):
        raise HTTPException(status_code=401, detail="missing bearer token")
    return authorization.split(" ", 1)[1].strip()


@app.post("/auth/login")
def login(body: LoginBody) -> dict:
    token = users.login(body.email, body.password)
    return {"access_token": token}


@app.get("/auth/me")
def me(authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    return {"user_id": user_id}


@app.get("/users/{user_id}")
def get_user_endpoint(user_id: int) -> dict:
    user = users.get_user(user_id)
    return {"id": user_id, "email": user["email"], "role": user["role"]}


@app.post("/users/{user_id}/promote")
def promote_endpoint(user_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.require_admin(token)
    user = users.promote_user(user_id)
    return {"id": user_id, "role": user["role"]}


@app.post("/orders")
def create_order_endpoint(
    body: CreateOrderBody,
    authorization: str = Header(...),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    items = [i.model_dump() for i in body.items]
    return orders.create_order(
        user_id=user_id,
        items=items,
        idempotency_key=idempotency_key,
        coupon=body.coupon,
    )


@app.post("/orders/{order_id}/refund")
def refund_endpoint(order_id: int, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    auth.get_current_user_id(token)
    return orders.refund_order(order_id)


@app.get("/inventory/{sku}")
def stock_endpoint(sku: str) -> dict:
    return {"sku": sku, "stock": inventory.get_stock(sku)}


@app.post("/validate/email")
def validate_email(email: str) -> dict:
    return {"valid": validators.is_valid_email(email)}


@app.get("/calc/sum")
def calc_sum(start: int, end: int) -> dict:
    return {"result": calculator.sum_inclusive(start, end)}


@app.patch("/users/me/email")
def change_email_endpoint(body: EmailBody, authorization: str = Header(...)) -> dict:
    token = _bearer(authorization)
    user_id = auth.get_current_user_id(token)
    return users.change_email(user_id, body.email)


