"""Signed outbound callbacks for third-party endpoints."""

from __future__ import annotations

import hashlib
import hmac
import json

from app import settings


class Endpoint:
    def __init__(self, url: str, secret: str, active: bool = True) -> None:
        self.url = url
        self.secret = secret
        self.active = active

    def disable(self) -> None:
        self.active = False

    def enable(self) -> None:
        self.active = True


_ENDPOINTS: list[Endpoint] = [
    Endpoint("https://hooks.example.invalid/shop", "dev-hook-secret"),
]
_DELIVERIES: list[dict] = []


def sign_payload(secret: str, body: str) -> str:
    digest = hmac.new(secret.encode("utf-8"), body.encode("utf-8"), hashlib.sha256)
    return digest.hexdigest()


def encode_body(payload: dict) -> str:
    return json.dumps(payload, sort_keys=True)


def active_endpoints() -> list[Endpoint]:
    return [item for item in _ENDPOINTS if item.active]


def register_endpoint(url: str, secret: str) -> Endpoint:
    item = Endpoint(url, secret)
    _ENDPOINTS.append(item)
    return item


def queue_delivery(kind: str, payload: dict) -> list[dict]:
    if not settings.webhooks_enabled():
        return []
    body = encode_body(payload)
    sent: list[dict] = []
    for endpoint in active_endpoints():
        rec = {
            "url": endpoint.url,
            "kind": kind,
            "signature": sign_payload(endpoint.secret, body),
        }
        _DELIVERIES.append(rec)
        sent.append(rec)
    return sent


def deliveries() -> list[dict]:
    return list(_DELIVERIES)


def last_delivery() -> dict | None:
    if not _DELIVERIES:
        return None
    return _DELIVERIES[-1]


def reset_store() -> None:
    _DELIVERIES.clear()
    for item in _ENDPOINTS:
        item.enable()

"""Staff macros and ticket drafts."""

from __future__ import annotations

from app import notifications


class Ticket:
    def __init__(self, user_id: int, subject: str, body: str) -> None:
        self.user_id = user_id
        self.subject = subject
        self.body = body
        self.status = "open"

    def close(self) -> None:
        self.status = "closed"

    def as_dict(self) -> dict:
        return {
            "user_id": self.user_id,
            "subject": self.subject,
            "body": self.body,
            "status": self.status,
        }


_TICKETS: list[Ticket] = []
_MACROS = {
    "shipping": "We shipped your parcel.",
    "refund": "We received your cancellation request.",
}


def open_ticket(user_id: int, subject: str, body: str) -> dict:
    ticket = Ticket(user_id, subject, body)
    _TICKETS.append(ticket)
    return ticket.as_dict()


def close_ticket(index: int) -> dict:
    ticket = _TICKETS[index]
    ticket.close()
    return ticket.as_dict()


def macro_text(name: str) -> str:
    return _MACROS.get(name, "")


def notify_ticket(user_id: int, subject: str) -> dict:
    return notifications.dispatch_notice(user_id, "support", subject)


def open_tickets() -> list[dict]:
    return [ticket.as_dict() for ticket in _TICKETS if ticket.status == "open"]


def all_tickets() -> list[dict]:
    return [ticket.as_dict() for ticket in _TICKETS]


def reset_store() -> None:
    _TICKETS.clear()

"""Seasonal campaigns and merchandising copy."""

from __future__ import annotations

from app import catalog, settings


class Campaign:
    def __init__(self, code: str, headline: str, active: bool = False) -> None:
        self.code = code
        self.headline = headline
        self.active = active

    def activate(self) -> None:
        self.active = True

    def deactivate(self) -> None:
        self.active = False


_CAMPAIGNS: dict[str, Campaign] = {
    "welcome": Campaign("welcome", "Thanks for shopping", True),
    "spring": Campaign("spring", "Spring refresh", False),
}


def get_campaign(code: str) -> Campaign | None:
    return _CAMPAIGNS.get(code)


def active_campaigns() -> list[str]:
    return [code for code, item in _CAMPAIGNS.items() if item.active]


def headline_for(code: str) -> str:
    item = get_campaign(code)
    return item.headline if item else ""


def activate(code: str) -> None:
    item = get_campaign(code)
    if item:
        item.activate()


def deactivate(code: str) -> None:
    item = get_campaign(code)
    if item:
        item.deactivate()


def featured_titles() -> list[str]:
    return [catalog.title_for(sku) for sku in catalog.known_skus()]


def storefront_banner() -> str:
    names = active_campaigns()
    if not names:
        return settings.mail_from()
    return headline_for(names[0])


def reset_store() -> None:
    for item in _CAMPAIGNS.values():
        item.deactivate()
    _CAMPAIGNS["welcome"].activate()

"""In-memory user store and login."""

from copy import deepcopy

from fastapi import HTTPException

from app import auth

_DEFAULT_USERS: dict[int, dict] = {
    1: {"email": "admin@example.com", "password": "adminpass1", "role": "admin"},
    2: {"email": "alice@example.com", "password": "alicepass1", "role": "user"},
    3: {"email": "bob@example.com", "password": "bobpass1", "role": "user"},
}

_USERS: dict[int, dict] = deepcopy(_DEFAULT_USERS)


def get_user(user_id: int) -> dict:
    """Return the user record for ``user_id``."""
    return _USERS[user_id]


def find_user_by_email(email: str) -> tuple[int, dict] | None:
    for uid, u in _USERS.items():
        if u["email"] == email:
            return uid, u
    return None


def login(email: str, password: str) -> str:
    """Verify credentials and return an access token."""
    match = find_user_by_email(email)
    if match is None:
        raise HTTPException(status_code=401, detail="invalid credentials")
    uid, user = match
    if user["password"] != password:
        raise HTTPException(status_code=401, detail="invalid credentials")
    from app import notifications

    notifications.capture_contact(uid, user["email"])
    return auth.create_token(user_id=uid)


def change_email(user_id: int, email: str) -> dict:
    from app import validators

    if not validators.is_valid_email(email) or not email:
        raise HTTPException(status_code=400, detail="invalid email")
    taken = find_user_by_email(email)
    if taken is not None and taken[0] != user_id:
        raise HTTPException(status_code=409, detail="email in use")
    user = get_user(user_id)
    user["email"] = email
    return {"id": user_id, "email": email, "role": user["role"]}


def promote_user(target_id: int) -> dict:
    user = get_user(target_id)
    user["role"] = "admin"
    return user


def reset_store() -> None:
    """Test helper — restore the seeded users."""
    from app import notifications

    _USERS.clear()
    _USERS.update(deepcopy(_DEFAULT_USERS))
    notifications.reset_store()
